285	export function viewOf({ folderPath, designDir, view, ext = '.eta' }) {
286	  if (!view.startsWith('@app/')) return { views: join(designDir, 'views'), template: `./${view}` };
287	  const file = normalize(join(folderPath, `${view.slice(5)}${extname(view) ? '' : ext}`));
