289	  if (!existsSync(file)) return { error: `There's no view at ${view} (looked for ${file.slice(folderPath.length + 1).split(sep).join('/')}).` };
290	  const base = file.slice(dirname(file).length + 1);
291	  return { views: dirname(file), template: `./${base.slice(0, base.length - extname(base).length)}` };
