1	// Live channels: server-sent events, one channel per key.
2	//
3	// A page subscribes with <div ko-connect="…/live?from=N">. What it receives is
4	// markup with ko-into, delivered by Koda like the out-of-band part of a
5	// response (reference: "A channel the server can speak on").
6	
7	export function createLive() {
8	  const channels = new Map();   // key -> Set<res>
9	
10	  const write = (res, message) => {
11	    res.write(String(message).split('\n').map(line => `data: ${line}`).join('\n') + '\n\n');
12	  };
13	
14	  return {
15	    /**
16	     * Start an event stream on `res`, send `initial` messages, then keep it
17	     * subscribed to `key`. `onClose` runs when the page goes away.
18	     */
19	    open(key, req, res, initial = [], { onClose = () => {} } = {}) {
20	      res.writeHead(200, {
21	        'content-type': 'text/event-stream; charset=utf-8',
22	        'cache-control': 'no-store',
23	        'connection': 'keep-alive',
24	        'x-accel-buffering': 'no',
25	      });
26	      res.write(': open\n\n');
27	      for (const message of initial) write(res, message);
28	
29	      if (!channels.has(key)) channels.set(key, new Set());
30	      channels.get(key).add(res);
31	      const keepAlive = setInterval(() => res.write(': ping\n\n'), 25000);
32	
33	      req.on('close', () => {
34	        clearInterval(keepAlive);
35	        channels.get(key)?.delete(res);
36	        if (channels.get(key)?.size === 0) channels.delete(key);
37	        onClose();
38	      });
39	    },
40	
41	    publish(key, message) {
42	      for (const res of channels.get(key) ?? []) write(res, message);
43	    },
44	
45	    closeAll() {
46	      for (const subscribers of channels.values()) for (const res of subscribers) res.end();
47	      channels.clear();
48	    },
49	  };
50	}
