17	    if (!designs.has(key)) designs.set(key, { version: 0, current: null, state: null, windows: 0 });
18	    return designs.get(key);
19	  };
20	
21	  const announce = key => {
22	    const design = of(key);
23	    design.version++;
24	    live.publish(designChannel(key), `design-changed:${design.version}`);
25	  };
26	
27	  return {
